def findNearestDrone(drones: list[list[int]], target: list[int]) -> int:
    tx, ty = target
    best_dist = 10**15
    best_idx = -1
    for i, (x, y) in enumerate(drones):
        d = abs(x - tx) + abs(y - ty)
        if d < best_dist:
            best_dist = d
            best_idx = i
    return best_idx

#include <vector>
#include <cmath>

class Solution {
public:
    int findNearestDrone(std::vector<std::vector<int>>& drones, std::vector<int>& target) {
        long long bestDist = 1e18;
        int bestIdx = -1;
        for (int i = 0; i < (int)drones.size(); ++i) {
            long long d = std::abs(drones[i][0] - target[0]) + std::abs(drones[i][1] - target[1]);
            if (d < bestDist) {
                bestDist = d;
                bestIdx = i;
            }
        }
        return bestIdx;
    }
};

class Solution {
    public int findNearestDrone(int[][] drones, int[] target) {
        long bestDist = Long.MAX_VALUE;
        int bestIdx = -1;
        for (int i = 0; i < drones.length; i++) {
            long d = Math.abs(drones[i][0] - target[0]) + Math.abs(drones[i][1] - target[1]);
            if (d < bestDist) {
                bestDist = d;
                bestIdx = i;
            }
        }
        return bestIdx;
    }
}

